# ★ 대화 모델 — 팀 통합 .env 스키마에 맞춰 env 로 뺐다(2026-07-31).
#   전에는 상수로 고정했다(비용 사고 방지). 이제 3축이 같은 방식으로 관리하기로 해서 외부화한다.
#   기본값은 코드에 남긴다 — clone 한 사람이 .env 에 이 키가 없어도 그대로 돌아가야 한다.
#
#   선정 근거(실측): 3.6-flash vs 3.1-lite 골든셋 34/34 동일 · 흔들림은 3.6 이 더 큼(3/7 vs 2/7)
#                    · 비용 15배 차 → lite 채택. 말투 우위는 착시였다(카드 턴에서 답이 폐기되고 있었음).
#   ※ 2.5-flash-lite 는 목록엔 있으나 이 키로 404(사용불가).
MODEL = ENV.get('COURSE_LLM_MODEL') or 'gemini-3.1-flash-lite'


def _int_env(key, default):
    """.env 의 정수 설정을 읽는다. 값이 없거나 숫자가 아니면 **기본값**.

    ⚠ 여기서 예외를 던지지 않는 이유: .env 오타 하나로 서버가 안 뜨면
      시연 직전에 못 고친다. 잘못된 값은 조용히 무시하고 기본값으로 돈다.
    """
    try:
        v = int(str(ENV.get(key) or '').strip())
        return v if v > 0 else default
    except (TypeError, ValueError):
        return default
#  (2026-07-28) GRADE='기능사' 제거 — 옛 자격증 검색에서 grade 필터로 쓰였으나 직업-먼저 전환으로 죽음.


# ── 슬롯 정의 ───────────────────────────────────────────────────────
#  ※ Gemini 는 enum 에 빈 문자열을 허용하지 않는다(400).
#    required 에 넣지 않음 → '모르면 생략'이 곧 미확인.
#  ★ 슬롯마다 '근거'를 함께 받는다 — 프롬프트로 부탁하는 대신 코드가 검증하기 위해서다.
#    모델이 값을 지어내려면 근거도 지어내야 하는데, 그건 원문 대조에서 걸린다.
#    (실측: "컴퓨터가 재밌어요" 만 말했는데 환경선호=실내 를 채우는 일이 반복됨)
def _slot(desc, enum=None):
    v = {'type': 'STRING'}
    if enum:
        v['enum'] = enum
    return {'type': 'OBJECT',
            'properties': {'값': v,
                           '근거': {'type': 'STRING',
                                    'description': '사용자가 실제로 한 말에서 그대로 인용'}},
            'required': ['값', '근거'],
            'description': desc}


#  ★★ 다중값 슬롯 (2026-08-04) — **한 사람은 여러 가지를 좋아할 수 있다.**
#
#  왜 바꾸나 — 실측으로 확인한 것:
#      1턴 「엄마가 아프셔서 제가 계속 챙겨요」 → 활동유형 = 돕기·돌봄
#      3턴 「손으로 만드는 게 편해요」        → 활동유형 = 만들기   ← **돕기·돌봄을 덮어씀**
#    merge() 도 verify_slots() 도 제대로 동작했다. LLM 도 제대로 뽑았다.
#    **스키마가 「사람은 한 가지만 좋아한다」고 전제한 것**이 원인이었다.
#
#  MultiWOZ 같은 표준 DST 는 슬롯이 단일값이어도 맞다 — hotel-area=north 는 **객관적 사실**이고
#  한 예약이 north 이면서 south 일 수 없다. 우리 슬롯은 **선호**다. 둘 다 참일 수 있다.
#  (CRS 문헌 CUPID 의 지적과 같다: 단일 표현으로는 상충하는 의도를 못 잡는다)
#
#  ⚠ 부정은 여기서 지우지 않는다. 「사람 상대는 힘들어요」에는 슬롯을 **안 채우고**(지금도 그렇다),
#    이미 담긴 값은 그대로 둔 채 **최종 선택(llm_pick)이 대화를 읽고** 피한다.
#    '해봤다'는 사실과 '하고 싶다'는 선호를 슬롯 단계에서 섞지 않으려는 것이다.
MULTI_SLOTS = ('관심분야', '활동유형', '다루는대상', '제약')
MULTI_MAX = 4          # 한 슬롯에 담을 최대 개수 — 무한정 쌓이면 질의가 흐려진다


#  ★★ 2026-08-08 — 「종류」: 그 값에 대한 **화자의 처지**.
#
#  왜 넣나 (실측 checks/fact_pref_probe.py) — 같은 「할머니를 돌보다」에 어미만 바꾼 6종이
#    **전부 동일하게** 활동유형=돕기·돌봄 으로 기록됐다. 「돌봐야 해요」(의무)와
#    「돌보고 싶어요」(희망)가 구분되지 않는다. 담을 «자리»가 없어서다.
#    그리고 「할머니 돌보느라 아무것도 못 해봤어요」가 «출처 user» 로 선호에 들어갔다.
#    우리 사용자군에게 가장 흔한 문장 형태가 정확히 그것이다.
#
#  근거(원문 확인) — 강제된 행동에서 선호를 읽으면 안 된다는 것은 경제학의 오래된 결론이다:
#    "When there are external constraints, it is more natural to assume that the
#     intentions and preferences of the individual are not known."
#    그리고 Gati·Krausz·Osipow 의 진로결정 어려움 분류(CDDQ) 는 「External Conflicts」를
#    독립 범주로 둔다 — 「개인의 선호와, 그에게 중요한 타인이 표명한 선호 사이의 간극」.
#    가족돌봄청년에게 돌봄이 정확히 그 자리다.
#
#  ⚠ 왜 «선호 3축에만» 넣나 — 실측(checks/kind_capability_test.py, 100케이스):
#      6슬롯 전체에 얹으면 8/14, 선호 3축 + 프롬프트 설명이면 75/79(95%).
#    세부관심·강점성향은 「원함/못함」이 성립하지 않고, 제약은 이미 제약이다.
#  ⚠ 정의를 프롬프트 «본문»에도 둔다(prompts.SYSTEM). 스키마 description 에만 두면
#    4,500토큰짜리 지시 속에서 흘린다 — 위 실측의 8/14 가 그 조건이었다.
KINDS = ['원함', '해봤음', '못함']
KIND_DESC = ('이 값에 대한 화자의 처지. '
             '원함=하고 싶다·좋다고 말했다. '
             '해봤음=해왔거나 하고 있다는 사실만 말했다(좋다고도 싫다고도 안 했다). '
             '못함=그것에 묶여 있거나 그것 때문에 다른 걸 못 했다(의무·불가피·좌절). '
             '해봤지만 «계속할 수 없어 그만뒀다»고 한 것도 못함이다 '
             '(「힘들어서 그만뒀어요」·「이제 못 하겠어요」). '
             '어미를 보라 — 「~하고 싶어요」와 「~해야 해요」는 정반대다. '
             '애매하면 해봤음. 원함으로 짐작하지 마라.')
#  종류별 무게 — can_land 가 쓴다. 0 이면 착지에 표를 안 준다(담기긴 한다).
KIND_W = {'원함': 1.0, '해봤음': 0.5, '못함': 0.0}


def _slot_multi(desc, enum=None, kind=False):
    v = {'type': 'STRING'}
    if enum:
        v['enum'] = enum
    props = {'값': v,
             '근거': {'type': 'STRING',
                     'description': '사용자가 실제로 한 말에서 그대로 인용'}}
    req = ['값', '근거']
    if kind:
        props['종류'] = {'type': 'STRING', 'enum': KINDS, 'description': KIND_DESC}
        req.append('종류')
    return {'type': 'ARRAY', 'description': desc,
            'items': {'type': 'OBJECT', 'properties': props, 'required': req}}


def as_list(x):
    """슬롯 값을 리스트로 — 옛 형식(문자열)도 그대로 받는다."""
    if isinstance(x, list):
        return [i for i in x if i]
    return [x] if x else []


def slot_text(x):
    """슬롯 값을 검색어에 쓸 문자열로."""
    return ' '.join(str(i) for i in as_list(x))

#  슬롯 재설계(2026-07-28) — 직업을 '특정'하는 축으로 5개. (환경·시간·비용 제거)
#    관심분야(무엇에) × 활동유형(어떻게) × 다루는대상(무엇으로) 이 직업을 가르고,
#    세부관심은 '넓게 남을 때' 좁히기(narrowing)로 채워지며, 강점성향은 보강 신호다.
#    활동유형·다루는대상은 enum('갇힌 출력') — 모델이 목록에서만 고른다.
#  ★ NCS 대분류 24개 — job_catalog.job_lcls_name 의 실제 값 그대로 (2026-08-04).
#    DB 를 직접 가리키는 유일한 슬롯이라, 다른 슬롯과 달리 '우리가 만든 어휘'가 아니다.
#    왜 필요한가(실측): 벡터 검색은 동사에 반응한다.
#      「만드는 일이 좋아요」→ 대분류 없이는 **누가 물어도** 가구제작·목공예·섬유공예
#        + 식품가공 → 떡제조·제빵·제과      + 기계 → 사출금형제작·레이저가공
#      「고치는 일 하고 싶어요」→ 없이는 수선·의장정비
#        + 전기·전자 → 로봇유지보수·원자력발전계측제어설비정비
#    분야를 모르면 '가장 만들기스러운 직업'이 나갈 뿐이다. 이게 「이상한 추천」의 정체였다.
NCS_LCLS = [
    '기계', '건설', '정보통신', '전기·전자', '환경·에너지·안전',
    '문화·예술·디자인·방송', '화학·바이오', '농림어업', '재료',
    '이용·숙박·여행·오락·스포츠', '금융·보험', '운전·운송', '경영·회계·사무',
    '섬유·의복', '인쇄·목재·가구·공예', '식품가공', '사회복지·종교', '영업판매',
    '법률·경찰·소방·교도·국방', '음식서비스', '보건·의료', '교육·자연·사회과학',
    '사업관리', '경비·청소',
]

#  ★ 2026-08-04 — '관심대분류'(24개 enum 배열)를 **스키마에서 뺐다.**
#    넣었던 이유는 위 NCS_LCLS 주석에 있고, 필터 효과 자체는 실측으로 확인됐다.
#    빼는 이유는 다른 데 있다 — **스키마에 필드를 더하면 다른 필드의 품질이 떨어진다.**
#    제약 디코딩은 모델을 평소 확률 경로에서 밀어내고, 그 대가가 추가한 필드가 아니라
#    **나머지 필드**에 나타난다("구조는 맞는데 내용이 틀린" 출력).
#    실측 정황: 이걸 추가한 뒤 골든셋 「지목」 태그 기준선이 7/7 → 4/7 로 떨어졌다.
#    ⇒ 기준선을 먼저 회복하고, 대분류가 정말 필요하면 **별도 호출**로 뽑는다(스키마를 안 건드리는 방식).
#    NCS_LCLS 상수와 대분류 필터 코드는 그대로 둔다 — think() 가 쓰고 있고, 되살리기 쉽게.
PROFILE_SCHEMA = {'type': 'OBJECT', 'properties': {
    #  ★ 앞 세 축은 **다중값**이다(2026-08-04, MULTI_SLOTS 주석 참고).
    #    한 사람이 「사람 돌보는 일」과 「손으로 만드는 일」을 둘 다 좋아할 수 있다.
    #    이번 발화에서 **새로 알게 된 것만** 담는다 — 기존 값은 시스템이 이어 붙인다.
    #  ★ 2026-08-08 — 앞 세 축에만 「종류」를 붙인다(kind=True). 근거는 KINDS 위 주석.
    '관심분야': _slot_multi('좋아한다·재밌다·해봤다고 말한 활동이나 대상 (일상어 그대로). '
                          '이번 발화에서 새로 나온 것만. 없으면 빈 배열', kind=True),
    '활동유형': _slot_multi('무슨 행위를 좋아하나 — 목록에서 고른다. 여러 개면 여러 개 다 담는다. '
                          '이번 발화에서 새로 나온 것만. 없으면 빈 배열',
                          ['만들기', '고치기·정비', '운전·조작', '돕기·돌봄', '가르치기',
                           '분석·연구', '관리·운영', '표현·창작', '판매·설득'], kind=True),
    '다루는대상': _slot_multi('일의 주 재료 — 목록에서 고른다. 여러 개면 여러 개 다 담는다. '
                           '이번 발화에서 새로 나온 것만. 없으면 빈 배열',
                           ['사람', '기계·설비', '컴퓨터·데이터', '자연·생물', '창작물', '숫자·문서'],
                           kind=True),
    #  ★ 2026-08-04 정의 확장 — 예전엔 예시가 기술 분야뿐이라('웹/게임/앱, 한식/제빵')
    #    모델이 «어르신»·«치매»·«장애인» 같은 **대상 세분화**를 세부관심으로 안 넣었다.
    #    실측: 「어르신 쪽이 편해요」 → {다루는대상: 사람} 만 남고 '어르신'이 통째로 사라짐.
    #    대화에서 제일 값진 정보가 버려지고 있었다.
    '세부관심': _slot('관심을 좁히는 구체 정보 — 분야(웹/게임/앱, 한식/제빵)든 '
                    '대상(어르신/아동/장애인/반려동물)이든 장소(병원/공장/학교)든 '
                    '"무엇을 콕 집었나"에 해당하면 담는다. 사용자가 말한 표현 그대로.'),
    '강점성향': _slot('잘하거나 편한 것 (손재주·꼼꼼함·체력·사교성·인내심 등). 말할 때만'),
    #  ★★ 제약 (2026-08-04 부활) — 2026-07-28 재설계 때 '시간제약·환경·비용'을 뺐었다.
    #    뺀 이유는 타당했다: **제약은 직업을 가르지 않는다**(「시간이 없다」로 직업이 좁혀지지 않음).
    #    그래서 이번에도 **검색어에는 넣지 않는다.** 되살린 이유는 따로 있다 —
    #      설계문서 954줄: 「상시시험 14종은 연 41~42회차 vs 일반 기능사 4.6회차 = 8배.
    #        ~~시간제약 슬롯과 직결~~ → 슬롯이 제거돼 **시간 없는 사용자를 식별할 근거가
    #        없으므로 개인화 불가**」 로 **보류**되어 있었다.
    #    그런데 그 데이터는 **이미 DB 에 들어와 있다**(실측: 제빵기능사 42회차 ·
    #    미용사(일반) 42 · 조리기능사류 41 · 굴착기/지게차운전 41 vs 일반 기능사 4~5).
    #    데이터가 없어서가 아니라 **누가 시간이 없는지 몰라서** 못 쓰고 있었다.
    #  쓰는 곳 — 검색어 아님:
    #    ① 자격증 정렬 : 시간부족이면 회차 많은 자격증을 먼저 (놓쳐도 곧 다음이 있다)
    #    ② llm_pick   : 후보 중 고를 때 제약과 부딪히는 것을 피한다
    #    ③ 덜다 라우팅 : 지금은 낱말 목록으로 감지 중인 것을 슬롯으로 승격
    '제약': _slot_multi('사용자가 말한 **현실적 부담**. 해당하는 것 전부. 없으면 빈 배열. '
                      '추측하지 말고 사용자가 실제로 말했을 때만 담는다',
                      ['시간부족', '비용부담', '체력부담', '대인부담', '학력부담']),
}}


# ── 한글 조사 (2026-08-05) ───────────────────────────────────────
#  왜 함수로 두나 — 조사를 코드가 붙이는 자리가 여러 군데다(카드 이유·안내 문구·버튼 라벨).
#  받침을 안 보고 고정 조사를 쓰면 **「건설기계정비이에요」** 같은 문장이 그대로 화면에 나간다
#  (2026-08-05 브라우저 확인에서 실제로 발견). 사용자가 카드에서 제일 먼저 읽는 문장이라 눈에 띈다.
def has_batchim(word):
    """한글 낱말의 마지막 글자에 받침이 있나.

    ※ 한글이 아닌 글자로 끝나면(영문·숫자·기호) False 로 본다 —
      「K-MOOC예요」가 「K-MOOC이에요」보다 자연스럽다.
    """
    w = re.sub(r'[\s·)\]』」>]+$', '', str(word or ''))
    if not w:
        return False
    ch = w[-1]
    if not ('가' <= ch <= '힣'):                  # 한글 음절이 아니면
        return False
    return (ord(ch) - 0xAC00) % 28 != 0          # 종성 인덱스가 0이면 받침 없음


def josa(word, with_batchim, without_batchim):
    """받침에 맞는 조사를 골라 붙인다. josa('제빵','이에요','예요') → '제빵이에요'."""
    return f'{word}{with_batchim if has_batchim(word) else without_batchim}'


#  ★ 모델이 쓴 문장의 조사 교정 (2026-08-05) ──────────────────────────
#  왜 또 필요한가 — 위 josa() 는 **코드가 조립하는** 문구에만 듣는다.
#    그런데 카드의 「AI 추천 이유」(job_reason)는 llm_pick 이 낸 **모델 문장이
#    그대로** 화면에 나간다. 실측(브라우저 확인) —
#      🤖「그중에 지금 바로 시작할 수 있는 게 **건설기계정비이에요**」
#    「정비」는 받침이 없으니 「예요」가 맞다. 모델은 이걸 자주 틀린다.
#    ⇒ josa() 를 아무리 잘 만들어도 이 자리는 안 고쳐진다. 별도로 태워야 한다.
#
#  ⚠ **문장 전체에 정규식을 돌리지 않는다.** 「사이에요」(사이+예요)처럼 낱말이
#    「이」로 끝나면 조사와 구분할 방법이 없어 「사예요」로 망가진다.
#    ⇒ **카드에 실제로 있는 이름 뒤에만** 고친다. 그 이름은 우리가 아는 문자열이므로
#      오탐이 구조적으로 불가능하다. (직업명·중분류명·자격증명)
_NAME_JOSA = (('이에요', '예요'), ('이라고', '라고'), ('이었', '였'))


def fix_name_josa(text, names):
    """카드에 있는 이름 뒤의 조사만 받침에 맞게 고친다. 그 외 문장은 건드리지 않는다."""
    out = str(text or '')
    if not out:
        return out
    for nm in names:
        nm = str(nm or '').strip()
        if not nm or nm not in out:
            continue
        has_b = has_batchim(nm)
        for with_b, without_b in _NAME_JOSA:
            #  올바른 형태는 josa() 가 정한다 — 받침 판정을 한 곳에서만 한다.
            right = josa(nm, with_b, without_b)
            wrong = f'{nm}{without_b if has_b else with_b}'
            if wrong != right:
                out = out.replace(wrong, right)
    return out


# ── 근거 검증 : 모델이 댄 근거가 실제 발화에 있는가 ─────────────────
def _clean(s):
    return re.sub(r'[^가-힣a-zA-Z0-9]', '', s or '')

def _grounded(evidence, user_msg):
    """근거의 핵심 어절이 발화 안에 있으면 인정. 조사·어미 차이는 허용한다."""
    ev, msg = _clean(evidence), _clean(user_msg)
    if not ev or not msg:
        return False
    if ev in msg:                                   # 그대로 인용한 경우
        return True
    toks = [t for t in re.split(r'\s+', (evidence or '').strip()) if len(_clean(t)) >= 2]
    if not toks:
        return False
    hit = sum(1 for t in toks if _clean(t)[:2] in msg)   # 어간 2글자로 대조
    return hit >= max(1, (len(toks) + 1) // 2)           # 절반 이상 맞으면 인정


def verify_slots(raw, user_msg, kinds_out=None):
    """모델이 채운 슬롯 중 '발화에 근거가 있는 것'만 통과시킨다.

    반환: (통과한 슬롯 dict, 버려진 목록)

    kinds_out
      ★ 2026-08-08 — 넘기면 «축별 대표 종류»를 채워 준다 {슬롯: '원함'|'해봤음'|'못함'}.
        반환값을 3개로 늘리지 않은 이유: checks/slot_ablation.py 가
        `slots, _ = verify_slots(...)` 로 받고 있어 조용히 깨진다.
      한 축에 값이 여럿이고 종류가 섞이면 **무게가 가장 큰 것**을 대표로 쓴다.
        「관심분야=[빵:원함, 돌봄:못함]」이면 그 축에는 진짜 선호(빵)가 있으므로 원함이다.
    """
    kept, dropped = {}, []
    for k, v in (raw or {}).items():
        #  ★ 다중값 슬롯(2026-08-04) — 항목마다 따로 근거를 대조한다.
        #    하나가 근거 없다고 나머지까지 버리지 않는다.
        if isinstance(v, list):
            vals = []
            for it in v:
                if not isinstance(it, dict):
                    if it:
                        vals.append(it)
                    continue
                val, ev = it.get('값'), it.get('근거')
                if not val:
                    continue
                if _grounded(ev, user_msg):
                    vals.append(val)
                    #  ★ 종류는 «통과한 값»의 것만 모은다. 버려진 값의 종류는 뜻이 없다.
                    #    2026-08-08 — «값마다» 담는다(mark_slot_kind 주석 참고).
                    kd = it.get('종류')
                    if kinds_out is not None and kd in KIND_W:
                        kinds_out.setdefault(k, {})[val] = kd
                else:
                    dropped.append(f'{k}={val} (근거 "{ev}" 가 발화에 없음)')
            if vals:
                kept[k] = list(dict.fromkeys(vals))
            continue
        if not isinstance(v, dict):                 # 혹시 옛 형식이 오면 그대로 통과
            if v:
                kept[k] = v
            continue
        val, ev = v.get('값'), v.get('근거')
        if not val:
            continue
        if _grounded(ev, user_msg):
            kept[k] = val
        else:
            dropped.append(f'{k}={val} (근거 "{ev}" 가 발화에 없음)')
    return kept, dropped

def notfound_reply(near):
    """'우리에게 없다'는 말은 코드가 쓴다.

    모델에게 맡기면 없는 자격증을 있다고 하거나, 얼버무리고 아무거나 권한다.
    없다는 사실 자체가 사용자에게 필요한 정보다 — 다른 데를 알아볼 수 있으니까.
    """
    #  직업 먼저(2026-07-28) — near 는 '가까운 직업'이다(예전엔 '가까운 자격증'이라 c['cert']였음).
    names = ' · '.join(n.get('job', '') for n in (near or [])[:3] if n.get('job'))
    msg = '말씀하신 일은 저희가 지금 다루는 범위에서는 딱 맞는 걸 찾지 못했어요.'
    if names:
        msg += f'\n\n비슷한 쪽으로는 {names} 같은 일이 있어요. 이 중에 끌리는 게 있으세요?'
    msg += '\n아니면 어떤 일을 하고 싶은지 편하게 말씀해 주셔도 좋아요.'
    return msg


#  ── 거부·번복 감지 (2026-08-04) ────────────────────────────────────────
#  실측 사고 — 「할머니 간병하면서 학교를 못 다녔어요」로 시작한 대화에서
#    1턴 [카드 일상생활기능지원] · 2턴 [카드 일상생활기능지원]
#    3턴 «근데 계속 그것만 하긴 좀»  →  [카드 **일상생활기능지원**]   ← 거부했는데 또 같은 것
#  원인: 슬롯(관심분야=간병, 활동유형=돕기·돌봄)이 한 번 차면 지워지지 않는다.
#  문헌도 같은 지점을 지적한다 — Correctable-DST(2022)의 Slot Detector,
#  AG-DST(2021)의 2-pass amendment 가 전부 '이전 상태를 뒤집는 장치'다.
#  다만 그것들은 학습된 모듈이라, 우리는 **코드가 신호를 잡고 그 직업을 배제**하는 방식으로 한다.
#  ⚠ 좁게 잡는다. '좀'·'별로' 같은 흔한 말만으로는 안 걸리게 — 오탐이 더 나쁘다.
#  ⚠ 이름 주의 — 아래쪽(rejects_or_questions)에 이미 `_REJECT` 가 있다. 목적이 다르다.
#    그쪽: 「이름을 말했지만 거부·되묻는 발화면 코드 DIRECT 로 확정하지 마라」(확정 방지)
#    이쪽: 「방금 준 카드를 물렸으니 그 직업을 빼고 다시 찾아라」(재검색)
#    그쪽 목록엔 '모르겠'이 있어 이 용도엔 오탐이다("잘 모르겠어요"는 거부가 아니다).
_REJECT_LAST = ('말고', '말구', '아니고', '아니라', '아닌데', '빼고', '싫어', '싫은',
                '그것만', '이것만', '그거만', '다른거', '다른걸', '다른게', '다른쪽', '딴거',
                '안맞', '안맞아', '별로예요', '별론데', '내키지', '부담스',
                #  ★★ 2026-08-06 — **거부를 못 알아들어 통째로 삼킨 실측이 있다.**
                #    페르소나 시험(문지아 · 요양보호사 자격증은 있으나 돌봄은 하기 싫은 사람):
                #      「돌보는 일은 안 한다고요. 아이든 노인이든 전부 **빼주세요**」
                #    위 목록에 '빼고'는 있는데 '빼주'가 없어서 **하나도 안 걸렸다.**
                #    그래서 ① 배제도 강등도 안 돌았고 ② 착지 뒤 재검색 억제가 그대로 걸려
                #    사용자의 **가장 강한 거부 발화가 통째로 무시되고 화제가 전환됐다.**
                #    반복 추천보다 이쪽이 나쁘다 — 사과조차 없이 못 들은 척이 된다.
                '빼주', '빼줘', '빼달', '제외', '안한다', '안 한다', '안할', '안 할',
                '하기싫', '하기 싫', '싫다고', '싫습니', '원치않', '원하지않',
                #  「아닌 **것** 같아요」 — 361행 주석이 none_of_these 쪽에만 적어 둔 형태다.
                #  「**이건** 좀 아닌 것 같아요」는 전체 부정이 아니라 이 카드 거부라 여기 있어야 한다.
                '아닌것', '아닌거')


#  ── 「이 중에 없음」 (2026-08-05) ────────────────────────────────────
#  위 _REJECT_LAST 는 「**그거** 말고」 — 하나를 콕 집어 물리는 말이다.
#  이것은 「**다** 아니다」 — 보여준 목록 전체가 안 맞는다는 말이고, 걸리는 말이 다르다.
#    「다 아닌 것 같은데요」 → '아닌데' 가 아니라 '아닌것'이라 _REJECT_LAST 에 안 걸린다(실측).
#    「이 중에 없어요」     → 어느 목록에도 없다.
#  안 걸리면 강등이 아예 안 돌아, 모델이 즉흥으로 답한다. 실측 —
#    칩 [요양지원·산후육아지원·보육] → 「다 아닌 것 같은데요」
#    → 「기계 쪽, 아니면 데이터를 정리하는 일처럼 **아예 다른 분야**는요?」
#    돌봄 동네를 통째로 떠났다. 그 동네엔 아직 가사지원·진로지원·병원안내가 남아 있는데.
#  ★ 근거 ①  ⚠️ **원문 미확인** (2026-08-05 검증 시도)
#    Josse et al. (2025), "Using the SOCcer occupation auto-coding tool to help
#      participants self-code their occupation in online questionnaires",
#      EPICOH **학회 초록** (정식 논문 아님)
#      https://oem.bmj.com/lookup/doi/10.1136/oemed-2025-EPICOHabstracts.215
#    주장: 「이 중에 없음」을 고른 사람을 전문가가 재코딩했더니 원래 목록 안에
#          정답이 있었던 비율이 27%(v1)·54%(v2).
#    ⚠ 위 URL 은 403 으로 막혀 원문을 못 봤다. **발표에서 인용하지 말 것.**
#      요약본(Liner)에서 온 수치이고, 요약본은 틀릴 수 있다.
#
#  ★ 근거 ②  ✅ **원문 확인됨** — 이걸 대신 쓰면 된다
#    Josse, P. R., Russ, D., Orszag, L., Peters, C. E., Shen-Tu, G., Vena, J. E.,
#      & Friesen, M. C. (2026). Evaluation of using the SOCcer automated occupation
#      auto-coding algorithm to assist expert coding of job descriptions.
#      *Annals of Work Exposures and Health*, 70(4).
#    원문: "Expert coders were **more likely to deviate from the SOCcer-suggested
#           list for jobs with low score/score differences (39% to 44%)**
#           than high score/score differences (11% to 13%)."
#    ⇒ 점수가 낮을 때 목록 이탈이 3~4배 잦다. 즉 「다 아니다」는 **후보가 약할 때**
#      나오는 신호지, 「그 동네가 아니다」라는 뜻이 아니다. 같은 결론에 더 단단한 근거다.
#
#  ⇒ 동네를 떠나지 않는다. 보여준 것만 강등하고 **같은 슬롯으로** 다시 찾는다.
#    (하드 배제가 아니라 강등인 것도 같은 이유다 — 남는 게 없으면 되살아난다)
_NONE_OF_THESE = ('다아니', '다아닌', '전부아니', '모두아니', '다틀리',
                  '중에없', '해당없', '다별로', '전부별로',
                  '다안맞', '전부안맞', '하나도안', '다마음에안')


def none_of_these(msg):
    """보여준 목록 **전체**가 안 맞는다는 말인가."""
    m = re.sub(r'\s+', '', msg or '')
    return any(t in m for t in _NONE_OF_THESE)


#  ── 알맹이 없는 맞장구 (2026-08-05 · 코드감사) ────────────────────────
#  왜 필요한가 — 주 질의(q)는 **사용자 원문**이다(2026-08-03에 그렇게 바꿨고 그건 옳다).
#    그런데 「착지 요청 문구는 검색어가 아니다」라는 예외는 wants_land 한 경우에만 걸려 있다.
#    코드가 ASK→SEARCH 로 **강제 승격한 턴**은 그 예외를 안 받는다. 실측 경로:
#      1턴 「빵 만드는 게 좋아요」 → 2축 충족, one_shot_land 로 보류
#      2턴 사용자가 「네」        → 승격 → **주 질의 = "네"**
#    _search_query 는 `if query: return query` 라 이때 **슬롯을 아예 안 쓴다.**
#    「빵」이 슬롯에 있는데 검색어에 한 글자도 안 들어간다.
#  ★ 논문 근거  ✅ **원문 확인됨** (2026-08-05) — 다만 **인용이 틀려 있어 고친다**
#    (전) Kononykhina, Haensch & Kreuter (2026), 119개 실험
#    (후) Kononykhina, O., **Schierholz, M.**, & Kreuter, F. (**2025**).
#         *The Impact of Question Framing on the Performance of Automatic
#          Occupation Coding.* **arXiv:2501.05584**
#         · 저자가 Haensch 가 아니라 Schierholz 다
#         · 2026 이 아니라 2025 다 (arXiv 2501 = 2025년 1월)
#         · **「119개 실험」은 확인되지 않는다** — 독일 split-ballot 실험이고
#           그런 숫자가 없다. 빼고 인용할 것.
#    원문 확인된 문장:
#      "how respondents describe their work matters more than any model
#       or design choice (ICC = 0.76)"
#    사용자의 서술이 가장 지배적인 변수인데, 그걸 「네」로 덮어쓰고 있었다.
#
#  ⚠ 같은 논문의 **다른 결과**도 알아둘 것 — 우리 설계와 충돌한다:
#      「질문에 **예시(보기)를 주면** 응답이 더 상세해지지만 **어휘 다양성이 줄어**
#        자동코딩 정확도가 떨어질 수 있다」
#    잇다의 _ASK_Q 는 보기를 준다(「사람·기계·컴퓨터 중에…」). 그건 대가가 있는 선택이다.
#    다만 RecQuest(arXiv 2512.13173)는 반대로 「잘 모르는 사용자는 보기·예시가 있는
#    유도형이 낫다」고 한다. 우리 사용자는 후자다 ⇒ 보기를 유지하되 대가를 알고 쓴다.
#  ⇒ 발화 **전체**가 맞장구뿐이면 이번 턴 질의를 비운다(= 슬롯으로 찾는다).
#    _UNCERTAIN_ONLY 와 같은 방식이다 — 뒤에 뭐가 붙으면 정보가 있는 것이므로 건드리지 않는다.
_THIN_ACK = frozenset((
    '네', '넵', '옙', '예', '응', '어', '음', '아', '오',
    '그래', '그래요', '그렇군요', '그렇구나', '그러네요', '그쵸', '그죠',
    '맞아', '맞아요', '맞습니다', '알겠어', '알겠어요', '알겠습니다',
    '좋아', '좋아요', '좋네요', '괜찮아요', '오케이', 'ok', 'ㅇㅋ', 'ㄴㅇ', 'ㅇㅇ',
))


def is_thin_ack(msg):
    """발화 전체가 알맹이 없는 맞장구인가 → 검색어로 쓰지 않는다."""
    m = _FILLER_RE.sub('', (msg or '').lower())
    return bool(m) and m in _THIN_ACK


def useless_answer(msg):
    """되물음에 대한 **답변**이 쓸모없는가 (2026-08-05).

    ★ 근거 — Sekulić et al., ECIR 2024 (arXiv 2401.11463), ClariQ 기반 유용성 분류:
        되물음-답변 쌍의 유용성 분포가 None **32%** / Answer 53% / Question 11% / 둘 다 6%
        그리고 쓸모없는 답을 그냥 갖다 쓰면 nDCG@3 가 **13% 떨어진다**.
        원문: "it is better not to use any information provided by such questions
               and answers, than to use it wrongly"
    우리 적응적 되물음은 **질문**은 검사했는데(_answered_already) **답변**은 안 했다.
    답이 「몰라요」·「네」·「아무거나」면 그게 그대로 다음 턴 검색어가 된다.
    ⇒ 쓸모없으면 그 답을 **검색어로 쓰지 않는다**.
    ⚠ 2026-08-06 정정 — 예전 주석은 「슬롯 근거로도 쓰지 않는다」였으나 그건 구현된 적이 없다.
      슬롯 쪽은 verify_slots → merge 가 평소대로 돈다(_grounded 는 근거가 발화에 있으면 통과).
      한쪽으로만 틀린다 — 버리는 쪽이라 최악이어도 지금까지 모은 슬롯으로 찾는다.
    """
    return is_thin_ack(msg) or is_uncertain(msg)


def rejects_last_card(msg):
    """직전 추천을 물리는 말인가 — 좁게만 잡는다."""
    m = re.sub(r'\s+', '', msg or '')
    return any(t in m for t in _REJECT_LAST)


#  ── 착지 요청 감지 (2026-08-04) ──────────────────────────────────────
