#    카드를 받는 길은 셋뿐이었다: ① 슬롯 2개가 차서 코드가 강제 승격(can_land)
#    ② 직업명을 콕 집음(DIRECT) ③ 좁히기 선택지 클릭.
#    「이제 됐으니 그냥 알려줘」라고 말해도 **그 말을 듣는 자리가 없었다.**
#  왜 이 사용자에게 중요한가 — 시간이 없다.
#    월드비전 2024 심층면접: 「17시간 주 7일 근무를 하며 살아왔는데」(사례 11) ·
#    「지금 당장 자기가 하는 것도 바쁘다 보니까 어떤 지원 사업이 있는지
