#    더 묻는 게 항상 친절인 것은 아니다 — **끝낼 권한을 사용자에게 준다.**
#  ⚠ 좁게 잡는다. '빨리'·'바로' 단독은 넣지 않는다 —
#    「빨리 돈 벌 수 있는 일이면 좋겠어요」는 착지 요청이 아니라 조건 진술이다.
