#    야간 제약을 지우면 뜻이 정반대가 된다. 그래서 ㉮ 는 계속 막는다.
#  왜 그래도 여나 — 실측(checks/fact_pref_probe.py, 2026-08-08): 제약에 들어온 값 3개가
